// Spectrum — daily word game. Plain JS, no build step for the site itself.
// Puzzle data is generated by build.py into puzzles/<id>/ (see README).

const MAX_GUESSES = 5;
const SHARDS = 256;
const FIT_THRESHOLD = 25;        // category fit is 0..100; lenient so real words are rarely refused
const ANGLES = [0, 45, 90, 135]; // each spoke's angle from vertical, degrees
const C = 300, RING = 268;       // chart centre and the ring where the end words sit
const R_STAR = 108;              // screen length of one unit along a line (lines are offset, so at most 2R from the centre)

// ---- Scoring: the one place to change the rule ----
// The score is the closest guess to the answer, measured as the mean absolute gap across the
// spectrums revealed so far (0..2) and mapped to 0..100. Only the exact answer scores 100.
function scoreGame(guesses, answerPos, revealed) {
  if (guesses.some(g => g.exact)) return 100;
  let best = Infinity;
  for (const g of guesses) {
    let gap = 0;
    for (let i = 0; i < revealed; i++) gap += Math.abs(g.pos[i] - answerPos[i]);
    best = Math.min(best, gap / revealed);
  }
  return Math.max(0, Math.min(99, Math.round(100 * (1 - best))));
}

// ---- State ----
let puzzle;            // {id, category, answer, answerPos, spectrums:[{low, high}], number, date}
let guesses = [];      // {word, pos:[4], fit, exact, final}
let over = false;
let started = false;
let current = 0;       // spoke being read: vertical in the star, bold in the wheel
let view = 0, target = 0, anim = null; // star rotation, degrees (unbounded so it can keep turning)
const shardCache = new Map();

const $ = id => document.getElementById(id);
const svg = $('chart');
const revealed = () => over ? 4 : Math.min(guesses.length + 1, 4);
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const normalise = s => s.trim().toLowerCase().replace(/[^a-z\s-]/g, '').replace(/[\s-]+/g, ' ').trim();

// ---- Word lookup: each puzzle's vocabulary is split into 256 shard files by a hash of the word ----
function fnv1a(s) {
  let h = 0x811c9dc5;
  for (const b of new TextEncoder().encode(s)) h = Math.imul(h ^ b, 0x01000193) >>> 0;
  return h;
}

async function shard(word) {
  const key = (fnv1a(word) % SHARDS).toString(16).padStart(2, '0');
  if (!shardCache.has(key)) {
    shardCache.set(key, fetch(`puzzles/${puzzle.id}/w/${key}.json`).then(r => r.ok ? r.json() : {}));
  }
  return shardCache.get(key);
}

// Positions (-1..1 on each spectrum) and category fit for a word or short phrase; null if unknown.
async function lookup(word) {
  const parts = word.split(' ');
  const entries = await Promise.all(parts.map(async p => (await shard(p))[p]));
  if (entries.some(e => !e)) return null;
  const pos = [0, 1, 2, 3].map(i => entries.reduce((s, e) => s + e[i], 0) / entries.length / 100);
  return { pos, fit: Math.min(...entries.map(e => e[4])) };
}

// ---- Geometry ----
// Screen point at distance t along the direction `deg` (0 = straight up), from the centre.
function pt(deg, t) {
  const a = deg * Math.PI / 180;
  return [C + t * Math.sin(a), C - t * Math.cos(a)];
}

function endWords(i, deg) {
  const sp = puzzle.spectrums[i], cls = `end${i === current ? ' cur' : ''}`;
  const [hx, hy] = pt(deg, RING), [lx, ly] = pt(deg, -RING);
  return `<text class="${cls}" data-i="${i}" x="${hx}" y="${hy + 5}" text-anchor="middle">${esc(sp.high)}</text>` +
         `<text class="${cls}" data-i="${i}" x="${lx}" y="${ly + 5}" text-anchor="middle">${esc(sp.low)}</text>`;
}

// ---- Star view: answer at the centre, each line offset so the answer sits where it belongs ----
const dir = deg => { const a = deg * Math.PI / 180; return [Math.sin(a), -Math.cos(a)]; };
const CAP = 7;                 // half-length of the bar across each end of a line
const WORD_GAP = 16;           // how far a guess word sits from its dot

// Where every guess sits on screen: on its own line at its miss, or (final guess) the one point whose
// reading along each line best matches its position on that spectrum.
function placements(rot, R) {
  return guesses.map(g => {
    if (!g.final) {
      const deg = ANGLES[g.index] - rot, t = (g.pos[g.index] - puzzle.answerPos[g.index]) * R, [x, y] = pt(deg, t);
      return { g, x, y, deg, t };
    }
    let px = 0, py = 0;
    ANGLES.forEach((a, i) => { const [ux, uy] = dir(a - rot); const d = 0.5 * (g.pos[i] - puzzle.answerPos[i]) * R; px += d * ux; py += d * uy; });
    return { g, x: C + px, y: C + py, deg: null, t: null };
  });
}

// Distance from a point to line i. Every line passes through the centre (its offset is along itself).
const lineDist = (x, y, i, rot) => { const [ux, uy] = dir(ANGLES[i] - rot); return Math.abs((x - C) * uy - (y - C) * ux); };

// Put each guess word beside its dot so that no word crosses a line, an end word, or another word:
// try both sides of the line, the diagonals and outward along the line, at two distances; take the
// nearest spot that clears everything, else the clearest; then push overlapping words apart.
function layoutWords(items, rot) {
  const width = w => w.length * 7;
  const out = [];
  for (const it of items) {
    const dirs = it.deg === null ? [0, 45, 90, 135, 180, 225, 270, 315]
      : [it.deg + 90, it.deg - 90, it.deg + 45, it.deg - 45, it.deg + 135, it.deg - 135];
    const wd = width(it.g.word), cands = [];
    for (const d of dirs) for (const k of [1, 1.9, 2.8, 4, 5.5]) {
      const [ux, uy] = dir(d), x = it.x + WORD_GAP * k * ux, y = it.y + WORD_GAP * k * uy;
      const anchor = ux > 0.3 ? 'start' : ux < -0.3 ? 'end' : 'middle';
      const x0 = anchor === 'start' ? x : anchor === 'end' ? x - wd : x - wd / 2;
      const box = [[x0, y - 7], [x0 + wd, y - 7], [x0, y + 7], [x0 + wd, y + 7], [x0 + wd / 2, y]];
      let clear = Infinity;
      for (let i = 0; i < revealed(); i++) {
        for (const [bx, by] of box) clear = Math.min(clear, lineDist(bx, by, i, rot)); // its own line included: the word must sit beside it, not on it
        for (const r of [RING, -RING]) { const [ex, ey] = pt(ANGLES[i] - rot, r); for (const [bx, by] of box) clear = Math.min(clear, Math.hypot(bx - ex, by - ey) - 18); }
      }
      cands.push({ x, y, anchor, clear, far: k });
    }
    const ok = cands.filter(c => c.clear >= 9).sort((a, b) => (a.far - b.far) || (b.clear - a.clear));
    cands.sort((a, b) => b.clear - a.clear);
    out.push({ ...(ok[0] || cands[0]), word: it.g.word, wd, dx: it.x, dy: it.y });
  }
  for (let pass = 0; pass < 4; pass++) for (let a = 0; a < out.length; a++) for (let b = a + 1; b < out.length; b++) {
    const A = out[a], B = out[b];
    const ax0 = A.anchor === 'start' ? A.x : A.anchor === 'end' ? A.x - A.wd : A.x - A.wd / 2;
    const bx0 = B.anchor === 'start' ? B.x : B.anchor === 'end' ? B.x - B.wd : B.x - B.wd / 2;
    if (ax0 < bx0 + B.wd && bx0 < ax0 + A.wd && Math.abs(A.y - B.y) < 15) B.y = A.y + 15;
  }
  return out;
}

function render() {
  if (!puzzle) return;
  const R = R_STAR, rot = view;
  let s = '';
  for (let i = 0; i < (started ? revealed() : 0); i++) { // the first line is drawn when Go is pressed
    const deg = ANGLES[i] - rot, a = puzzle.answerPos[i], cur = i === current;
    const lo = (-1 - a) * R, hi = (1 - a) * R, [x1, y1] = pt(deg, lo), [x2, y2] = pt(deg, hi), [px, py] = dir(deg + 90);
    s += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#111" stroke-width="${cur ? 2.5 : 1.2}"/>`;
    // End caps: a short bar across each end so the extent of the spectrum is unmistakable.
    for (const [x, y] of [[x1, y1], [x2, y2]])
      s += `<line x1="${x - CAP * px}" y1="${y - CAP * py}" x2="${x + CAP * px}" y2="${y + CAP * py}" stroke="#111" stroke-width="${cur ? 2.5 : 1.5}" stroke-linecap="round"/>`;
    s += `<line data-i="${i}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="transparent" stroke-width="18" style="cursor:pointer"/>`;
    s += endWords(i, deg);
  }
  const ps = placements(rot, R);
  for (const p of ps) {
    if (p.deg === null) for (let i = 0; i < revealed(); i++) { // dotted drops from the final point to each line
      const [ux, uy] = dir(ANGLES[i] - rot), t = (p.x - C) * ux + (p.y - C) * uy;
      s += `<line x1="${p.x}" y1="${p.y}" x2="${C + t * ux}" y2="${C + t * uy}" stroke="#999" stroke-width="1" stroke-dasharray="2 3"/>`;
    }
    s += `<circle cx="${p.x}" cy="${p.y}" r="5" fill="${p.deg === null ? '#111' : '#fff'}" stroke="#111" stroke-width="1.7"/>`;
  }
  for (const l of layoutWords(ps, rot)) {
    // A word that had to move well away from its dot gets a thin leader so the pair stays obvious.
    if (l.far >= 1.9) {
      const ex = l.anchor === 'start' ? l.x - 3 : l.anchor === 'end' ? l.x + 3 : l.x, ey = l.y + (l.anchor === 'middle' ? (l.y > l.dy ? -8 : 8) : 0);
      const ang = Math.atan2(ey - l.dy, ex - l.dx);
      s += `<line x1="${l.dx + 6 * Math.cos(ang)}" y1="${l.dy + 6 * Math.sin(ang)}" x2="${ex}" y2="${ey}" stroke="#999" stroke-width="1"/>`;
    }
    s += `<text class="tag" x="${l.x}" y="${l.y + 4}" text-anchor="${l.anchor}">${esc(l.word)}</text>`;
  }
  s += `<circle cx="${C}" cy="${C}" r="7" fill="#111"/>`;
  svg.innerHTML = s;
  $('legend').textContent = !started ? '' : `● ${over ? `answer: ${puzzle.answer}` : 'answer'}, at the centre   ○ guess   ● final guess, one point read against every line`;
}

// ---- Rotation (star view). Lines are symmetric, so spoke i is vertical whenever view ≡ ANGLES[i] mod 180 ----
const fwd = i => ((ANGLES[i] - target) % 180 + 180) % 180; // anticlockwise degrees to bring spoke i upright

function setCurrent(i, delta) {
  current = i;
  if (delta === undefined) { const f = fwd(i); delta = f > 90 ? f - 180 : f; } // shortest way
  target += delta;
  const from = view, to = target, start = performance.now(), dur = 550;
  cancelAnimationFrame(anim);
  const step = now => {
    const k = Math.min(1, (now - start) / dur);
    view = from + (to - from) * (k < 0.5 ? 2 * k * k : 1 - (-2 * k + 2) ** 2 / 2);
    render();
    if (k < 1) anim = requestAnimationFrame(step);
  };
  anim = requestAnimationFrame(step);
}

// Turn one way (dir = +1 clockwise, -1 anticlockwise) to the next revealed spoke.
function turn(dir) {
  let best = null;
  for (let i = 0; i < revealed(); i++) {
    const a = (dir > 0 ? (180 - fwd(i)) % 180 : fwd(i)) || 180; // 180 = flip the current spoke
    if (!best || a < best.a) best = { i, a };
  }
  setCurrent(best.i, dir > 0 ? -best.a : best.a);
}

// ---- Readout: what each guess tells you ----
function hintFor(g, i) {
  const gap = g.pos[i] - puzzle.answerPos[i];
  if (Math.abs(gap) < 0.12) return `${puzzle.spectrums[i].low}↔${puzzle.spectrums[i].high}: spot on`;
  const word = puzzle.spectrums[i][gap > 0 ? 'low' : 'high'];
  return `${Math.abs(gap) > 0.6 ? 'much ' : ''}more ${word}`;
}

function renderReadout() {
  $('readout').innerHTML = guesses.map((g, k) => {
    const hint = g.exact ? 'the answer!' : (g.final ? [0, 1, 2, 3] : [g.index]).map(i => hintFor(g, i)).join(' · ');
    return `<li><span class="n">${k + 1}</span><span class="w">${esc(g.word)}</span><span class="hint">${hint}</span></li>`;
  }).join('');
}

// ---- Game flow ----
function msg(text) { $('message').textContent = text; }

function start() {
  started = true;
  $('start').hidden = true;
  $('guess-form').hidden = false;
  render();
  $('guess').focus();
  save();
}

async function submitGuess(e) {
  e.preventDefault();
  if (over) return;
  const word = normalise($('guess').value);
  if (!word) return;
  if (guesses.some(g => g.word === word)) return msg(`You already guessed "${word}".`);
  $('submit').disabled = true;
  const entry = await lookup(word);
  $('submit').disabled = false;
  if (!entry) return msg(`"${word}" isn't a word I know.`);
  if (word !== puzzle.answer && entry.fit < FIT_THRESHOLD) return msg(`"${word}" doesn't look like ${puzzle.category.toLowerCase()} to me — try another word.`);
  $('guess').value = '';
  msg('');
  addGuess(word, entry);
  save();
}

function addGuess(word, entry) {
  const index = guesses.length;
  guesses.push({ word, pos: entry.pos, fit: entry.fit, exact: word === puzzle.answer, final: index === 4, index });
  renderReadout();
  if (word === puzzle.answer || guesses.length === MAX_GUESSES) return endGame();
  if (guesses.length < 4) setCurrent(guesses.length, 45);
  else { msg('Final guess — all four spectrums are showing.'); $('message').style.color = '#111'; render(); }
}

function endGame() {
  over = true;
  $('guess-form').hidden = true;
  msg('');
  const solved = guesses.some(g => g.exact);
  const score = scoreGame(guesses, puzzle.answerPos, 4);
  $('result').textContent = solved
    ? `Got it in ${guesses.length}! The answer was "${puzzle.answer}". Score ${score}.`
    : `The answer was "${puzzle.answer}". Score ${score}.`;
  $('share-text').textContent = `Spectrum #${puzzle.number} ${solved ? '🎯' : '❌'} ${solved ? guesses.length : 'X'}/${MAX_GUESSES} · ${score}`;
  $('share').hidden = false;
  render();
}

// ---- Persistence: today's game survives a refresh ----
function save() {
  try { localStorage.setItem(`spectrum:${puzzle.id}:${puzzle.date}`, JSON.stringify({ started, words: guesses.map(g => g.word) })); } catch {}
}

async function restore() {
  let saved;
  try { saved = JSON.parse(localStorage.getItem(`spectrum:${puzzle.id}:${puzzle.date}`)); } catch {}
  if (!saved || !saved.started) return;
  start();
  for (const w of saved.words) {
    if (over) break;
    const entry = await lookup(w);
    if (entry) addGuess(w, entry);
  }
  save(); // start() saved an empty list; write the replayed guesses back
  view = target = ANGLES[current];
  render();
}

// ---- Wiring ----
$('go').addEventListener('click', start);
$('guess-form').addEventListener('submit', submitGuess);
$('copy').addEventListener('click', () => navigator.clipboard.writeText($('share-text').textContent).then(() => { $('copy').textContent = 'Copied'; }));
svg.addEventListener('click', e => {
  const i = e.target.dataset && e.target.dataset.i;
  if (i !== undefined && Number(i) < revealed()) setCurrent(Number(i));
});
document.addEventListener('keydown', e => {
  if (!started || e.target.tagName === 'INPUT' && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) return;
  // Right brings the line to the right of the upright one upright (the chart turns anticlockwise), left the reverse.
  if (e.key === 'ArrowRight' || e.key === 'ArrowUp') { e.preventDefault(); turn(-1); }
  if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') { e.preventDefault(); turn(1); }
});

// ---- Load today's puzzle ----
(async () => {
  try {
    const index = await fetch('puzzles/index.json').then(r => r.json());
    const now = new Date();
    const date = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    // ?puzzle=<id> plays any puzzle for testing; ?fresh forgets a saved game for it.
    const params = new URLSearchParams(location.search);
    const id = params.get('puzzle') || index.days[date];
    if (!id) throw new Error(`no puzzle scheduled for ${date} — run build.py`);
    if (params.has('fresh')) { try { localStorage.removeItem(`spectrum:${id}:${date}`); } catch {} }
    puzzle = await fetch(`puzzles/${id}/puzzle.json`).then(r => r.json());
    puzzle.answerPos = puzzle.answerPos.map(v => v / 100);
    puzzle.date = date;
    puzzle.number = Math.round((Date.parse(date) - Date.parse(index.launch)) / 864e5) + 1;
    $('sub').textContent = `#${puzzle.number} · ${now.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' })} · ${puzzle.category}`;
    render();
    $('go').disabled = false;
    await restore();
  } catch (err) {
    $('sub').textContent = `Couldn't load today's puzzle (${err.message}). Serve this folder over http.`;
  }
})();
